<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';require_login();if(($_SESSION['user_role']??'')!=='student'){redirect('dashboard.php');}
$pageTitle='Mijn geld';$error='';$success='';
$categories=['Salaris','Studiefinanciering','Huur','Boodschappen','Studie','Vervoer','Abonnementen','Vrije tijd','Sparen','Overig'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    $type=$_POST['type']??'';$amount=str_replace(',','.',trim($_POST['amount']??''));$category=trim($_POST['category']??'');$description=trim($_POST['description']??'');$date=$_POST['transaction_date']??date('Y-m-d');
    if(!in_array($type,['income','expense'],true)){$error='Kies inkomsten of uitgaven.';}
    elseif(!is_numeric($amount)||(float)$amount<=0|| (float)$amount>1000000){$error='Vul een geldig bedrag in.';}
    elseif(!in_array($category,$categories,true)){$error='Kies een geldige categorie.';}
    elseif(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$error='Vul een geldige datum in.';}
    else{$stmt=$pdo->prepare('INSERT INTO transactions(user_id,type,amount,category,description,transaction_date) VALUES(?,?,?,?,?,?)');$stmt->execute([$_SESSION['user_id'],$type,(float)$amount,$category,$description,$date]);$success='Je transactie is opgeslagen.';}
}
$stmt=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) expense FROM transactions WHERE user_id=? AND MONTH(transaction_date)=MONTH(CURRENT_DATE()) AND YEAR(transaction_date)=YEAR(CURRENT_DATE())");$stmt->execute([$_SESSION['user_id']]);$totals=$stmt->fetch();$income=(float)$totals['income'];$expense=(float)$totals['expense'];
$stmt=$pdo->prepare("SELECT category,SUM(amount) total FROM transactions WHERE user_id=? AND type='expense' AND MONTH(transaction_date)=MONTH(CURRENT_DATE()) AND YEAR(transaction_date)=YEAR(CURRENT_DATE()) GROUP BY category ORDER BY total DESC");$stmt->execute([$_SESSION['user_id']]);$byCategory=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT * FROM transactions WHERE user_id=? ORDER BY transaction_date DESC,id DESC LIMIT 30");$stmt->execute([$_SESSION['user_id']]);$transactions=$stmt->fetchAll();
include __DIR__.'/includes/header.php';?>
<section class="page-intro"><div class="container"><span class="eyebrow">Financieel overzicht</span><h1>Grip op je geld.</h1><p>Registreer inkomsten en uitgaven, bekijk je maandtotalen en ontdek welke categorieën het meeste kosten.</p></div></section><section class="content-section"><div class="container">
<?php if($error): ?><div class="form-error"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="form-success"><?= e($success) ?></div><?php endif; ?>
<div class="money-summary"><div class="money-card positive"><span>Inkomsten deze maand</span><strong><?= euro($income) ?></strong></div><div class="money-card negative"><span>Uitgaven deze maand</span><strong><?= euro($expense) ?></strong></div><div class="money-card <?= $income-$expense<0?'negative':'positive' ?>"><span>Verschil deze maand</span><strong><?= euro($income-$expense) ?></strong></div></div>
<div class="two-column"><div><div class="panel"><h2>Nieuwe transactie</h2><form class="form-stack" method="post"><div class="field"><label for="type">Soort</label><select id="type" name="type" required><option value="expense">Uitgave</option><option value="income">Inkomst</option></select></div><div class="field"><label for="amount">Bedrag in euro's</label><input id="amount" name="amount" type="number" min=".01" max="1000000" step=".01" required placeholder="Bijv. 42,50"></div><div class="field"><label for="category">Categorie</label><select id="category" name="category" required><?php foreach($categories as $c): ?><option><?= e($c) ?></option><?php endforeach; ?></select></div><div class="field"><label for="transaction_date">Datum</label><input id="transaction_date" name="transaction_date" type="date" value="<?= date('Y-m-d') ?>" required></div><div class="field"><label for="description">Omschrijving (optioneel)</label><input id="description" name="description" maxlength="180" placeholder="Bijv. boodschappen bij supermarkt"></div><button class="button" type="submit">Transactie opslaan</button></form></div>
<div class="panel"><div class="panel-title"><h2>Recente transacties</h2><span class="tag">Laatste 30</span></div><?php if($transactions): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Datum en omschrijving</th><th>Categorie</th><th>Bedrag</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><?= date('d-m-Y',strtotime($t['transaction_date'])) ?><br><span class="job-meta"><?= e($t['description']?:$t['category']) ?></span></td><td><?= e($t['category']) ?></td><td style="font-weight:800;color:<?= $t['type']==='income'?'#116149':'#9b4437' ?>"><?= $t['type']==='income'?'+':'−' ?> <?= euro($t['amount']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="job-meta">Je hebt nog geen transacties ingevoerd.</p><?php endif; ?></div></div>
<aside><div class="panel"><h3>Uitgaven per categorie</h3><p class="job-meta">Deze maand, van hoog naar laag.</p><?php if($byCategory): foreach($byCategory as $cat): $percent=$expense>0?min(100,((float)$cat['total']/$expense)*100):0; ?><div style="margin:17px 0"><div style="display:flex;justify-content:space-between;gap:12px;font-size:13px;margin-bottom:6px"><span><?= e($cat['category']) ?></span><strong><?= euro($cat['total']) ?></strong></div><div style="height:8px;background:#edf1ed;border-radius:9px;overflow:hidden"><div style="height:100%;width:<?= $percent ?>%;background:#116149;border-radius:9px"></div></div></div><?php endforeach; else: ?><p class="job-meta">Voer uitgaven in om hier je categorieën te zien.</p><?php endif; ?></div><div class="panel"><h3>Goed om te weten</h3><p class="job-meta">CashJob haalt geen bankgegevens op. Voer je inkomsten en uitgaven zelf in. Je ziet hier alleen transacties van je eigen account.</p></div></aside></div>
</div></section><?php include __DIR__.'/includes/footer.php'; ?>
